import{j as e}from"./motion-BJIk69pZ.js";import{C as s}from"./Card-Bd5hMyZz.js";import{B as a}from"./index-CuDC_SzC.js";import{e as i}from"./react-BQIr6j2H.js";import"./charts-BYFiz5UO.js";const r=[{h:"Local data storage",p:"Studifree stores your learning data on your device using IndexedDB and LocalStorage. Your lessons, decks, cards, quizzes and settings are not uploaded to a Studifree server."},{h:"Visitor notifications",p:"When you open the deployed Studifree website, the site may send a visitor notification email through EmailJS. This notification contains the visit time, page URL, your IP address (looked up through ipify), browser user agent, language, screen size, timezone, referrer and platform. It is used only to understand visits to the site. It is not linked to your study data. EmailJS acts as a third-party delivery service for these notifications."},{h:"Optional location sharing",p:"The deployed site asks once whether you want to share your device location. No coordinates are read from your browser unless you press “Allow location”. If you allow, your latitude, longitude and location accuracy in metres are sent in the same visitor notification together with the visit time, page URL and IP address. If you decline, no location is collected or sent. Your choice is stored in this browser and can be reset in Settings → Privacy."},{h:"API-key handling",p:"If you add an API key, it is stored in your browser. It is sent only to the AI provider you choose when you use AI features. Browser storage is not completely secure against someone with access to your browser profile, so avoid shared devices. You can remove the key at any time in AI Setup. Studifree does not log your key or include it in error messages."},{h:"Third-party AI providers",p:"When you use AI features, your prompts and uploaded content are sent to the selected provider, subject to that provider's terms and privacy policy. Google processes Gemini API requests under your own account and may apply quotas or charges."},{h:"File processing",p:"PDFs and images are processed locally in your browser to extract text. File contents may be sent to your AI provider if you request AI features on them."},{h:"Data deletion",p:"You can delete all local data from Settings. Clearing browser data also removes it. Deleting local data does not delete visitor notification emails already delivered, or records held by third-party providers."},{h:"Export",p:"You can export your study data as JSON from Settings at any time."},{h:"AI limitations",p:"AI output may be inaccurate or inappropriate. You are responsible for verifying content before relying on it."},{h:"User responsibility for uploaded content",p:"You must have the rights to any content you upload."}];function p(){const o=i();return e.jsxs("div",{className:"px-5 pt-6 pb-4 max-w-3xl mx-auto space-y-6",children:[e.jsxs("div",{children:[e.jsx("h1",{className:"text-2xl font-semibold text-ink",children:"Privacy Policy (Draft)"}),e.jsx("p",{className:"text-xs text-faint mt-1",children:"Draft for review by a qualified professional before public launch."})]}),r.map(t=>e.jsxs(s,{children:[e.jsx("h2",{className:"font-semibold text-ink mb-2",children:t.h}),e.jsx("p",{className:"text-muted leading-relaxed",children:t.p})]},t.h)),e.jsxs(s,{children:[e.jsx("h2",{className:"font-semibold text-ink mb-2",children:"Questions about privacy"}),e.jsx("p",{className:"text-sm text-muted mb-3",children:"The FAQ and Help Centre explain how location consent, AI keys and local storage work in practice."}),e.jsxs("div",{className:"flex flex-wrap gap-2",children:[e.jsx(a,{size:"sm",variant:"secondary",onClick:()=>o("/about#faq"),children:"Read the FAQ"}),e.jsx(a,{size:"sm",variant:"secondary",onClick:()=>o("/help"),children:"Open Help Centre"})]})]})]})}export{p as default};
